import{_ as t,o as e,c as o,a2 as c}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"AgentPay 统一支付状态机与故障恢复规范 (T1.1 Specification v2.1)","description":"","frontmatter":{},"headers":[],"relativePath":"specs/state-machine.md","filePath":"specs/state-machine.md","lastUpdated":1792396280000}'),n={name:"specs/state-machine.md"};function a(r,d,i,s,l,h){return e(),o("div",null,[...d[0]||(d[0]=[c(`<h1 id="agentpay-统一支付状态机与故障恢复规范-t1-1-specification-v2-1" tabindex="-1">AgentPay 统一支付状态机与故障恢复规范 (T1.1 Specification v2.1) <a class="header-anchor" href="#agentpay-统一支付状态机与故障恢复规范-t1-1-specification-v2-1" aria-label="Permalink to &quot;AgentPay 统一支付状态机与故障恢复规范 (T1.1 Specification v2.1)&quot;">​</a></h1><blockquote><p><strong>版本</strong>：v2.1.0 (T1.1 统一规范：双轨结算架构)<br><strong>状态</strong>：<strong>已定稿 (Approved Specification)</strong><br><strong>前置任务</strong>：T0.1 / T0.2 (基线已冻结：<code>v0.1.0-poc-baseline</code>)<br><strong>相关规范</strong>：<a href="./wallet-ledger">specs/wallet-ledger-spec.md</a> (T1.7 虚拟钱包与账本规范)<br><strong>机器可读向量</strong>：<a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/conformance/state-machine.json" target="_blank" rel="noreferrer"><code>specs/conformance/state-machine.json</code></a></p></blockquote><hr><h2 id="_1-核心设计原则" tabindex="-1">1. 核心设计原则 <a class="header-anchor" href="#_1-核心设计原则" aria-label="Permalink to &quot;1. 核心设计原则&quot;">​</a></h2><ol><li><strong>三条状态线严格正交分离</strong>： <ul><li><strong>支付意图（PaymentIntent）</strong>：业务层端到端请求生命周期；</li><li><strong>结算（Settlement）</strong>：资金划转状态，支持<strong>双轨支付方式（Payment Method）</strong>： <ul><li><code>onchain</code>（链上结算）：x402 挑战签名、区块链广播与确认；</li><li><code>wallet</code>（平台内部虚拟钱包）：强事务资金冻结（Hold）、确权扣费（Capture）与解冻释放（Release）。</li></ul></li><li><strong>业务履约（Fulfillment）</strong>：上游目标 API 资源/结果实际交付状态。</li></ul></li><li><strong><code>unknown</code> 为一等状态</strong>： <ul><li>结算或履约结果不确定时，<strong>严禁直接归为成功，也严禁直接归为失败</strong>。</li><li>钱包扣费在数据库本地强事务中完成，本身无结算 unknown；但<strong>若履约 unknown，钱包冻结必须保持锁定并转 <code>needs_review</code></strong>，严禁私自释放或扣款。</li></ul></li><li><strong>终态绝对不可变（Terminal State Immutability）</strong>： <ul><li>进入终态（<code>completed</code>, <code>failed</code>, <code>expired</code>, <code>rejected</code>, <code>confirmed</code>, <code>released</code>）后状态只读，只允许追加不可变审计事件。</li></ul></li><li><strong>禁止盲目重试与禁止静默降级</strong>： <ul><li>对 <code>unknown</code> 状态严禁重复发起扣款或重新广播；</li><li><strong>严禁自动降级</strong>：若钱包余额不足，必须直接返回 <code>402 Insufficient Balance</code>，绝对不能静默降级为链上扣费，防止用户产生非预期的链上资金支出。</li></ul></li></ol><hr><h2 id="_2-标识与多租户幂等契约" tabindex="-1">2. 标识与多租户幂等契约 <a class="header-anchor" href="#_2-标识与多租户幂等契约" aria-label="Permalink to &quot;2. 标识与多租户幂等契约&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标识符</th><th>作用域与责任</th><th>约束规则</th></tr></thead><tbody><tr><td><code>request_id</code></td><td>单次 HTTP 请求链路追踪</td><td>网关在入站时生成（UUIDv4），贯穿全链路结构化日志</td></tr><tr><td><code>idempotency_key</code></td><td>客户端业务级幂等重试</td><td>租户级唯一。同一租户内相同的 key 严格映射到同一个 <code>payment_intent_id</code></td></tr><tr><td><code>payment_intent_id</code></td><td>一笔高层支付意图</td><td>一个 <code>idempotency_key</code> 唯一对应一个 intent（格式：<code>pi_...</code>）</td></tr><tr><td><code>hold_id</code></td><td>虚拟钱包单笔冻结单号</td><td>钱包路径专属，一个 intent 唯一绑定一个有效 Hold（格式：<code>hld_...</code>）</td></tr><tr><td><code>settlement_id</code></td><td>一次结算记录</td><td>一个 intent 在同一时刻最多对应一个有效结算（格式：<code>stl_...</code>）</td></tr><tr><td><code>fulfillment_id</code></td><td>一次上游业务交付尝试</td><td>一个 intent 严格对应一个履约记录（格式：<code>ful_...</code>）</td></tr></tbody></table><hr><h2 id="_3-双轨结算与履约状态流转" tabindex="-1">3. 双轨结算与履约状态流转 <a class="header-anchor" href="#_3-双轨结算与履约状态流转" aria-label="Permalink to &quot;3. 双轨结算与履约状态流转&quot;">​</a></h2><h3 id="_3-1-链上结算路径-on-chain-path" tabindex="-1">3.1 链上结算路径 (On-Chain Path) <a class="header-anchor" href="#_3-1-链上结算路径-on-chain-path" aria-label="Permalink to &quot;3.1 链上结算路径 (On-Chain Path)&quot;">​</a></h3><p>遵循 <strong>方案 A（先结算后履约）</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>authorized ──▶ submit ──▶ [submitted] ──▶ [pending] ──▶ [confirmed]</span></span>
<span class="line"><span>                                                             │ (dispatch)</span></span>
<span class="line"><span>                                                             ▼</span></span>
<span class="line"><span>                                                    [fulfillment: in_progress]</span></span>
<span class="line"><span>                                                             ├─ 2xx ─▶ completed</span></span>
<span class="line"><span>                                                             ├─ 4xx ─▶ refund_required</span></span>
<span class="line"><span>                                                             └─ 5xx ─▶ needs_review</span></span></code></pre></div><h3 id="_3-2-虚拟钱包结算路径-internal-wallet-path" tabindex="-1">3.2 虚拟钱包结算路径 (Internal Wallet Path) <a class="header-anchor" href="#_3-2-虚拟钱包结算路径-internal-wallet-path" aria-label="Permalink to &quot;3.2 虚拟钱包结算路径 (Internal Wallet Path)&quot;">​</a></h3><p>遵循 <strong>“冻结 → 履约 → 确认扣费/释放”</strong> 闭环：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>authorized ──▶ hold ──▶ [held] ──(dispatch)──▶ [fulfillment: in_progress]</span></span>
<span class="line"><span>                                                        ├─ 2xx ─▶ capture ──▶ confirmed (完成)</span></span>
<span class="line"><span>                                                        ├─ 4xx ─▶ release ──▶ released (未扣费释放)</span></span>
<span class="line"><span>                                                        └─ 5xx ─▶ 保持 held ──▶ needs_review (人工核实)</span></span></code></pre></div><p><strong>双轨对比优势</strong>：</p><ul><li>在钱包路径中，上游明确失败（4xx）时直接在库内事务中 <code>release</code> 释放冻结，<strong>完全不需要复杂的退款/补偿流程</strong>，买方零资金损失，卖方亦不会白送服务。</li></ul><hr><h2 id="_4-三维状态定义与合法迁移矩阵" tabindex="-1">4. 三维状态定义与合法迁移矩阵 <a class="header-anchor" href="#_4-三维状态定义与合法迁移矩阵" aria-label="Permalink to &quot;4. 三维状态定义与合法迁移矩阵&quot;">​</a></h2><h3 id="_4-1-支付意图-paymentintent" tabindex="-1">4.1 支付意图 (PaymentIntent) <a class="header-anchor" href="#_4-1-支付意图-paymentintent" aria-label="Permalink to &quot;4.1 支付意图 (PaymentIntent)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>当前状态</th><th>触发事件</th><th>目标新状态</th><th>说明与前置守卫</th></tr></thead><tbody><tr><td><code>created</code></td><td><code>challenge_issued</code></td><td><code>challenged</code></td><td>仅链上路径：402 响应送出</td></tr><tr><td><code>created</code></td><td><code>payload_verified</code></td><td><code>authorized</code></td><td>仅钱包路径：API Key 及预算校验通过</td></tr><tr><td><code>created</code></td><td><code>policy_denied</code></td><td><code>rejected</code></td><td>策略拒绝、风控拦截或钱包欠费冻结</td></tr><tr><td><code>challenged</code></td><td><code>payload_verified</code></td><td><code>authorized</code></td><td>链上路径：买方携带合法签名重新请求</td></tr><tr><td><code>challenged</code></td><td><code>payload_invalid</code></td><td><code>rejected</code></td><td>签名无效、篡改或格式错误</td></tr><tr><td><code>challenged</code></td><td><code>timeout</code></td><td><code>expired</code></td><td>超过挑战 TTL（默认 300 秒）未提交</td></tr><tr><td><code>authorized</code></td><td><code>settlement_confirmed</code></td><td><code>completed</code></td><td>链上 confirmed 且履约成功，或钱包 capture 成功</td></tr><tr><td><code>authorized</code></td><td><code>settlement_failed</code></td><td><code>failed</code></td><td>链上结算失败，或钱包冻结额度不足</td></tr><tr><td><code>authorized</code></td><td><code>settlement_released</code></td><td><code>failed</code></td><td>钱包路径：上游失败解冻，意图正常关闭未计费</td></tr><tr><td><code>authorized</code></td><td><code>authorization_expired</code></td><td><code>expired</code></td><td>链上授权过期且结算尚未开始</td></tr><tr><td><code>authorized</code></td><td><code>recovery_deadline_exceeded</code></td><td><code>needs_review</code></td><td>结算或履约持续 unknown 超过恢复期限</td></tr><tr><td><code>needs_review</code></td><td><code>manual_resolved_confirmed</code></td><td><code>completed</code></td><td>人工介入核实已到账并交付</td></tr><tr><td><code>needs_review</code></td><td><code>manual_resolved_failed</code></td><td><code>failed</code></td><td>人工介入核实未交付且关闭意图</td></tr></tbody></table><h3 id="_4-2-结算-settlement" tabindex="-1">4.2 结算 (Settlement) <a class="header-anchor" href="#_4-2-结算-settlement" aria-label="Permalink to &quot;4.2 结算 (Settlement)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>当前状态</th><th>触发事件</th><th>目标新状态</th><th>对应支付方式与规则</th></tr></thead><tbody><tr><td><code>not_started</code></td><td><code>hold_acquired</code></td><td><code>held</code></td><td>【钱包】在数据库事务中成功冻结额度</td></tr><tr><td><code>not_started</code></td><td><code>hold_failed</code></td><td><code>failed</code></td><td>【钱包】可用余额不足或账户冻结</td></tr><tr><td><code>held</code></td><td><code>capture</code></td><td><code>confirmed</code></td><td>【钱包】上游 2xx，确认扣费入账（终态）</td></tr><tr><td><code>held</code></td><td><code>release</code></td><td><code>released</code></td><td>【钱包】上游 4xx，解冻恢复可用余额（终态）</td></tr><tr><td><code>not_started</code></td><td><code>submit_ok</code></td><td><code>submitted</code></td><td>【链上】广播成功获取 tx_hash</td></tr><tr><td><code>not_started</code></td><td><code>submit_rejected_definitely</code></td><td><code>failed</code></td><td>【链上】节点直接拒绝</td></tr><tr><td><code>not_started</code></td><td><code>submit_timeout</code></td><td><code>unknown</code></td><td>【链上】提交超时，状态未知</td></tr><tr><td><code>submitted</code></td><td><code>seen_on_chain</code></td><td><code>pending</code></td><td>【链上】交易进入内存池或已出块</td></tr><tr><td><code>submitted</code></td><td><code>query_timeout</code></td><td><code>unknown</code></td><td>【链上】查询超时</td></tr><tr><td><code>pending</code></td><td><code>confirmations_reached</code></td><td><code>confirmed</code></td><td>【链上】达到 1 个区块确认（终态）</td></tr><tr><td><code>pending</code></td><td><code>reverted</code></td><td><code>failed</code></td><td>【链上】交易执行 Revert 回滚（终态）</td></tr><tr><td><code>pending</code></td><td><code>query_timeout</code></td><td><code>unknown</code></td><td>【链上】状态轮询超时</td></tr><tr><td><code>unknown</code></td><td><code>query_found_confirmed</code></td><td><code>confirmed</code></td><td>【链上】对账核实已打包确认</td></tr><tr><td><code>unknown</code></td><td><code>query_found_failed</code></td><td><code>failed</code></td><td>【链上】对账核实已失败且过期未花费</td></tr><tr><td><code>unknown</code></td><td><code>query_found_pending</code></td><td><code>pending</code></td><td>【链上】重新查到待确认交易</td></tr><tr><td><code>unknown</code></td><td><code>query_still_unknown</code></td><td><code>unknown</code></td><td>【链上】状态依然未知</td></tr></tbody></table><h3 id="_4-3-业务履约-fulfillment" tabindex="-1">4.3 业务履约 (Fulfillment) <a class="header-anchor" href="#_4-3-业务履约-fulfillment" aria-label="Permalink to &quot;4.3 业务履约 (Fulfillment)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>当前状态</th><th>触发事件</th><th>目标新状态</th><th>说明与安全守卫</th></tr></thead><tbody><tr><td><code>not_started</code></td><td><code>dispatch</code></td><td><code>in_progress</code></td><td>链上要求 <code>settlement==confirmed</code>；钱包要求 <code>settlement==held</code></td></tr><tr><td><code>in_progress</code></td><td><code>upstream_2xx</code></td><td><code>succeeded</code></td><td>上游交付成功（触发钱包 capture）</td></tr><tr><td><code>in_progress</code></td><td><code>upstream_4xx</code></td><td><code>failed</code></td><td>上游客户端入参错误未执行（触发钱包 release）</td></tr><tr><td><code>in_progress</code></td><td><code>upstream_5xx</code></td><td><code>unknown</code></td><td>上游服务端异常，不可假定未执行（钱包保持 held）</td></tr><tr><td><code>in_progress</code></td><td><code>upstream_timeout</code></td><td><code>unknown</code></td><td>连接断开或读超时（钱包保持 held）</td></tr><tr><td><code>unknown</code></td><td><code>upstream_status_query_ok</code></td><td><code>succeeded</code></td><td>幂等查询证实已成功（补发 capture）</td></tr><tr><td><code>unknown</code></td><td><code>upstream_status_query_failed</code></td><td><code>failed</code></td><td>幂等查询证实未执行（补发 release）</td></tr><tr><td><code>unknown</code></td><td><code>recovery_deadline_exceeded</code></td><td><code>unknown</code></td><td>超过最大恢复期，标记待人工核查</td></tr></tbody></table><hr><h2 id="_5-对外派生组合视图-composite-view" tabindex="-1">5. 对外派生组合视图（Composite View） <a class="header-anchor" href="#_5-对外派生组合视图-composite-view" aria-label="Permalink to &quot;5. 对外派生组合视图（Composite View）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>结算状态 (Settlement)</th><th>履约状态 (Fulfillment)</th><th>派生展示状态 (Display Status)</th><th>业务解释</th></tr></thead><tbody><tr><td><code>held</code></td><td><code>not_started</code> / <code>in_progress</code></td><td><code>WALLET_HOLD_PROCESSING</code></td><td>钱包已预留额度，正在调用上游服务</td></tr><tr><td><code>unknown</code> / <code>pending</code> / <code>submitted</code></td><td><code>not_started</code></td><td><code>SETTLEMENT_IN_PROGRESS</code></td><td>链上支付确认中</td></tr><tr><td><code>confirmed</code></td><td><code>in_progress</code></td><td><code>FULFILLMENT_IN_PROGRESS</code></td><td>扣费已确认，服务交付中</td></tr><tr><td><code>confirmed</code></td><td><code>succeeded</code></td><td><code>COMPLETED</code></td><td>交易成功完成</td></tr><tr><td><code>confirmed</code></td><td><code>failed</code></td><td><code>SETTLED_FULFILLMENT_FAILED_REFUND_REQUIRED</code></td><td>链上已扣款但履约失败，待补偿退款</td></tr><tr><td><code>confirmed</code></td><td><code>unknown</code></td><td><code>SETTLED_FULFILLMENT_UNKNOWN_NEEDS_REVIEW</code></td><td>扣款已确认，履约异常待排查</td></tr><tr><td><code>released</code></td><td><code>failed</code></td><td><code>RELEASED_UNBILLED</code></td><td>钱包额度已释放，未产生任何实际扣款</td></tr><tr><td><code>failed</code></td><td><code>not_started</code></td><td><code>PAYMENT_FAILED</code></td><td>支付失败，未扣款</td></tr></tbody></table>`,29)])])}const _=t(n,[["render",a]]);export{u as __pageData,_ as default};
